import{_ as t,a as e,b as o,c as r,d,e as n}from"./chunks/ee-ohos-12.YBQ8g5AA.js";import{_ as s}from"./chunks/ee-ohos-2.C7lmEPa0.js";import{_ as i,o as f,c as l,a3 as c}from"./chunks/framework.BveOjhN0.js";const _=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"11.harmonyos/00.introduction.md","filePath":"11.harmonyos/00.introduction.md","lastUpdated":1783502384000}'),p={name:"11.harmonyos/00.introduction.md"};function m(u,a,g,v,h,b){return f(),l("div",null,[...a[0]||(a[0]=[c('<div class="hero" data-v-5f34d73f><div class="hero-badges" data-v-5f34d73f><span class="badge badge--star" data-v-5f34d73f>⭐ 8000+ Star</span><span class="badge badge--version" data-v-5f34d73f>🚀 v5</span><span class="badge badge--ohos" data-v-5f34d73f>🪶 HarmonyOS</span></div><h1 class="hero-title" data-v-5f34d73f>ElectronEgg: v5 Upgrade — Easily Build HarmonyOS Apps</h1><div class="hero-actions" data-v-5f34d73f><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-5f34d73f>GitHub Repo →</a><a class="btn btn--ghost" href="#wrapping-up" data-v-5f34d73f>Join Community</a></div></div><blockquote data-v-5f34d73f><p data-v-5f34d73f>One codebase, packaged for Windows, Mac, and Linux — and now it runs directly on HarmonyOS. ElectronEgg v5 brings HarmonyOS support.</p></blockquote><h2 id="introduction" tabindex="-1" data-v-5f34d73f>Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;" data-v-5f34d73f>​</a></h2><p data-v-5f34d73f>Since it was open-sourced, <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-5f34d73f>ElectronEgg</a>&#39;s vision has stayed simple: <strong data-v-5f34d73f>empower every developer to master desktop software development</strong>. It brings front-end and back-end engineering practices into desktop development, wrapping Electron&#39;s complexity behind a clean controller / service / preload layered architecture. The framework has now amassed <strong data-v-5f34d73f>8000+ Stars</strong> across the web, validated by long-term use across many teams — you can use it with confidence.</p><p data-v-5f34d73f>Building on this, v5 delivers a major upgrade — and one of its headline capabilities is: <strong data-v-5f34d73f>effortlessly build HarmonyOS apps</strong>.</p><p data-v-5f34d73f>After repeated attempts, we finally got ElectronEgg running on HarmonyOS devices. It&#39;s still in the <strong data-v-5f34d73f>testing phase</strong>, but the entire workflow already works end to end — see the screenshots below.</p><h2 id="harmonyos-support-one-codebase-running-on-harmonyos" tabindex="-1" data-v-5f34d73f>HarmonyOS Support: One Codebase, Running on HarmonyOS <a class="header-anchor" href="#harmonyos-support-one-codebase-running-on-harmonyos" aria-label="Permalink to &quot;HarmonyOS Support: One Codebase, Running on HarmonyOS&quot;" data-v-5f34d73f>​</a></h2><p data-v-5f34d73f>In the past, porting an Electron app to HarmonyOS essentially meant &quot;rewriting it from scratch&quot;. v5 automatically extracts your build artifacts into the HarmonyOS HAP, where they are loaded by the HAP project&#39;s web engine. <strong data-v-5f34d73f>Your existing ElectronEgg business code runs as a HarmonyOS app with almost no changes.</strong></p><p data-v-5f34d73f>Below are real screenshots of the ElectronEgg demo app running on HarmonyOS:</p><blockquote data-v-5f34d73f><p data-v-5f34d73f>App installed on the HarmonyOS system</p></blockquote><div class="center-logo" data-v-5f34d73f><img src="'+t+'" alt="logo" data-v-5f34d73f></div><p data-v-5f34d73f><img src="'+e+'" alt="ElectronEgg demo in the HarmonyOS AppCenter" data-v-5f34d73f></p><blockquote data-v-5f34d73f><p data-v-5f34d73f>App launching</p></blockquote><p data-v-5f34d73f><img src="'+s+'" alt="ElectronEgg demo launching" data-v-5f34d73f></p><blockquote data-v-5f34d73f><p data-v-5f34d73f>Framework feature demo: communication, controllers, services and other capabilities work normally on HarmonyOS</p></blockquote><p data-v-5f34d73f><img src="'+o+'" alt="ElectronEgg demo feature showcase" data-v-5f34d73f></p><blockquote data-v-5f34d73f><p data-v-5f34d73f>Local image loading demo</p></blockquote><p data-v-5f34d73f><img src="'+r+'" alt="ElectronEgg demo feature showcase" data-v-5f34d73f></p><blockquote data-v-5f34d73f><p data-v-5f34d73f>Dock bar demo</p></blockquote><p data-v-5f34d73f><img src="'+d+'" alt="ElectronEgg demo feature showcase" data-v-5f34d73f></p><blockquote data-v-5f34d73f><p data-v-5f34d73f>Web page loading demo</p></blockquote><p data-v-5f34d73f><img src="'+n+'" alt="ElectronEgg demo feature showcase" data-v-5f34d73f></p><p data-v-5f34d73f>As you can see, a desktop app originally built for Windows / Mac runs smoothly on HarmonyOS — from installation to every feature. That&#39;s the core message of v5&#39;s HarmonyOS support: <strong data-v-5f34d73f>cross-platform is no longer a slogan; HarmonyOS is a first-class citizen.</strong></p><h2 id="what-else-is-new-in-v5" tabindex="-1" data-v-5f34d73f>What Else Is New in v5 <a class="header-anchor" href="#what-else-is-new-in-v5" aria-label="Permalink to &quot;What Else Is New in v5&quot;" data-v-5f34d73f>​</a></h2><p data-v-5f34d73f>Beyond HarmonyOS support, v5 also gives the framework core a fairly thorough refactor:</p><ul data-v-5f34d73f><li data-v-5f34d73f>Full TypeScript refactor: every API now has complete type definitions.</li><li data-v-5f34d73f>Dual module output: supports both CJS and ESM formats.</li><li data-v-5f34d73f>Pino logging: a more powerful logging system.</li><li data-v-5f34d73f>Bundle registry: faster startup.</li><li data-v-5f34d73f>Main-process bundling: main-process code can be bundled just like front-end code.</li><li data-v-5f34d73f>Build config overhaul: many fine-grained control options added.</li><li data-v-5f34d73f>Encryption upgrade: more secure.</li><li data-v-5f34d73f>ee-bin overhaul: now ships a complete TypeScript type system.</li></ul><h2 id="who-is-it-for" tabindex="-1" data-v-5f34d73f>Who Is It For <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who Is It For&quot;" data-v-5f34d73f>​</a></h2><ul data-v-5f34d73f><li data-v-5f34d73f>Developers who want to build desktop software with a front-end stack (Vue / React / HTML)</li><li data-v-5f34d73f>Teams that need to ship internal tools, admin consoles, or office software as desktop apps</li><li data-v-5f34d73f>Products that must cover Windows, Mac, Linux, <strong data-v-5f34d73f>and HarmonyOS</strong></li><li data-v-5f34d73f>Teams looking to lower Electron&#39;s learning curve and want a clear architecture</li></ul><p data-v-5f34d73f>Whether you&#39;re a front-end, back-end, ops, or client developer, you can get started quickly.</p><h2 id="wrapping-up" tabindex="-1" data-v-5f34d73f>Wrapping Up <a class="header-anchor" href="#wrapping-up" aria-label="Permalink to &quot;Wrapping Up&quot;" data-v-5f34d73f>​</a></h2><p data-v-5f34d73f>Desktop software — office tools, personal utilities — will remain a real, lasting need on the PC for the next decade. ElectronEgg exists to make building it simple, and now that simplicity extends to HarmonyOS.</p><p data-v-5f34d73f>The framework is already widely used in clients for accounting, government, enterprise, healthcare, education, stock trading, ERP, entertainment, video and more — feel free to use it with confidence.</p><div class="tip custom-block" data-v-5f34d73f><p class="custom-block-title" data-v-5f34d73f>Open Source &amp; Community</p><ul data-v-5f34d73f><li data-v-5f34d73f>GitHub: <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-5f34d73f>https://github.com/dromara/electron-egg</a></li><li data-v-5f34d73f>Gitee: <a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-5f34d73f>https://gitee.com/dromara/electron-egg</a></li></ul></div><p data-v-5f34d73f>If it helps you, a Star is appreciated — and come join the community to chat.</p>',34)])])}const S=i(p,[["render",m],["__scopeId","data-v-5f34d73f"]]);export{_ as __pageData,S as default};
